args.body:
// 泵运行状态监控
// 每5秒检查运行状态
var runStatus = readTag("PUMP_101_RUN");
var pressure = readTag("PUMP_101_PRESSURE");
var flow = readTag("PUMP_101_FLOW");

// 如果泵在运行但压力或流量异常，记录诊断信息
if (runStatus == 1) {
    if (pressure < 0.5) {
        logWarning("泵 101 运行中但压力过低 - 可能空转！");
    }
    if (flow < 5) {
        logWarning("泵 101 运行中但流量过低 - 检查出口阀门！");
    }
}

